return {
  protect: {
    hook: "onDefenceResult", result: "damaged", damageType: "Wounds",
    scope: "zoneMate", group: "armour.t1.martyr",
    when: (H, actor) => H.condition.has(actor, "ready"),
    async promptOnPlayer(H, actor, ctx) {
      const candidates = ctx.candidateIds.map(id => game.actors.get(id));
      const incoming = Math.max(0, ctx.damageValue - 1);
      const hint = `${actor.name} is about to take ${ctx.damageValue} Wounds. The martyr takes ${incoming} instead and expends Ready.`;
      if (candidates.length === 1) {
        return await H.ask.confirm({
          title: "Martyr", bodyHtml: foundry.utils.escapeHTML(`${hint} Have ${candidates[0].name} take the hit?`),
          yesLabel: "Take the hit", noLabel: "Skip",
        }) ? { martyrId: candidates[0].id } : false;
      }
      const martyrId = await H.ask.one({
        title: "Martyr", label: "Martyr (takes the hit)", hint, applyLabel: "Take the hit",
        options: candidates.map(h => ({ value: h.id, label: h.name })),
      });
      return martyrId ? { martyrId } : false;
    },
    async applyOnGM(H, actor, ctx, choice) {
      const martyr = game.actors.get(choice.martyrId);
      await H.condition.set(martyr, "ready", false);
      const incoming = Math.max(0, ctx.damageValue - 1);
      await H.resource.adjust(martyr, { wounds: -incoming });
      await H.chat.post(`${martyr.name} uses Martyr to protect ${actor.name}, suffering ${incoming} Wound damage.`, martyr);
      return { damageRedirected: true };
    },
  },
};
